+// Freezing the reading at endTime makes the discount below zero, so an honest stake is paid in
+// full however late it is unstaked. Callable by anyone, once per stake, batchable via multicall.
+function finalizeStake(IncentiveKey memory key, uint256 tokenId) external override {
+    require(block.timestamp >= key.endTime, 'JunoswapV3Staker::finalizeStake: incentive not ended');
+    Stake storage stored = stakes[tokenId][IncentiveId.compute(key)];
+    require(stored.liquidity != 0 && !stored.finalized, 'JunoswapV3Staker::finalizeStake: nothing to freeze');
+    stored.secondsInsideFinal = uint32(_measureUptime(key, deposits[tokenId], stored));
+    stored.finalized = true;
+}

 function _measureUptime(IncentiveKey memory key, Deposit memory deposit, Stake memory stake)
     private view returns (uint256)
 {
     (, , uint32 secondsInside) = key.pool.snapshotCumulativesInside(deposit.tickLower, deposit.tickUpper);
     uint256 inside = uint256(uint32(secondsInside - stake.secondsInsideInitial));
+    // at most (now - endTime) of that growth accrued after the incentive ended; drop it
+    uint256 postEnd = block.timestamp > key.endTime ? block.timestamp - key.endTime : 0;
+    return inside > postEnd ? inside - postEnd : 0;
 }

